window.ARGUMENTS=[{"id": "hinder", "titel": "Windturbinegeluid veroorzaakt ernstige hinder, al bij lage geluidsniveaus", "sterkte": "Sterk", "sterkte_uitleg": "Consistente dosis-responsrelatie in tientallen studies, systematische reviews en een meta-analyse; door de WHO als gezondheidseffect erkend.", "kern": "Hoe meer windturbinegeluid, hoe meer ernstige hinder. Windturbinegeluid is bij hetzelfde dB(A)-niveau hinderlijker dan verkeers- of industriegeluid.", "steun": [{"id": 300, "punt": "Health Canada-studie (1.238 deelnemers): ernstige hinder nam toe naarmate het berekende windturbinegeluidniveau hoger was."}, {"id": 435, "punt": "Windturbinegeluid veroorzaakt hinder bij lagere geluidsniveaus dan andere omgevingsgeluidbronnen."}, {"id": 311, "punt": "Bij hetzelfde A-gewogen niveau werd windturbinegeluid hinderlijker gevonden dan wegverkeersgeluid, vooral bij amplitudemodulatie."}, {"id": 278, "punt": "Ook bij moderne 3–5 MW-turbines bestaat een duidelijke relatie tussen geluidsniveau en hinder binnenshuis."}, {"id": 469, "punt": "Nederlandse studie: hogere berekende geluidsniveaus hingen samen met meer hinder."}, {"id": 439, "punt": "Nederlandse schatting: circa 1.500 inwoners ondervinden waarschijnlijk binnenshuis ernstige hinder van windturbinegeluid."}, {"id": 363, "punt": "Systematische review: dosis-responsrelatie met hinder en zelfgerapporteerde slaapverstoring."}, {"id": 346, "punt": "Meta-analyse: hogere kans op hinder en slaapverstoring bij meer blootstelling."}], "extern": [{"label": "WHO Environmental Noise Guidelines (2018): aanbeveling windturbinegeluid onder 45 dB Lden, omdat geluid daarboven samenhangt met nadelige gezondheidseffecten", "url": "https://iris.who.int/bitstream/handle/10665/343936/WHO-EURO-2018-3287-43046-60243-eng.pdf"}], "verweer": [{"claim": "Hinder is geen gezondheidseffect.", "studies": [], "weerlegging": "De WHO baseert haar aanbeveling van 45 dB Lden juist op nadelige gezondheidseffecten, met ernstige hinder als kernuitkomst. Hinder is bovendien de schakel naar slaapverstoring en stress."}, {"claim": "Hinder komt vooral door houding, zichtbaarheid en gevoel van oneerlijkheid, niet door het geluid.", "studies": [65, 227], "weerlegging": "Niet-akoestische factoren versterken hinder, maar de dosis-responsrelatie met het geluidsniveau blijft in grote studies (Health Canada, Nederland, Finland) overeind. Dat procesfactoren meespelen, maakt de hinder niet minder reëel; het pleit voor zorgvuldiger besluitvorming."}], "tekst": "Uit peer-reviewed onderzoek blijkt een consistente dosis-responsrelatie tussen windturbinegeluid en ernstige hinder (Schmidt & Klokker, 2014; Onakpoya et al., 2015; Michaud et al., 2016). Windturbinegeluid veroorzaakt hinder bij lagere geluidsniveaus dan andere omgevingsgeluidbronnen (Janssen et al., 2011) en wordt bij hetzelfde A-gewogen niveau als hinderlijker ervaren dan wegverkeersgeluid (Schäffer et al., 2016). Dit geldt ook voor moderne turbines van 3–5 MW (Hongisto et al., 2017). De WHO beveelt daarom aan windturbinegeluid onder 45 dB Lden te houden, omdat geluid boven dit niveau samenhangt met nadelige gezondheidseffecten. Indiener verzoekt het bevoegd gezag inzichtelijk te maken hoeveel woningen in het plangebied boven deze waarde uitkomen en hoeveel ernstig gehinderden het project naar verwachting veroorzaakt.", "groep": "gezondheid"}, {"id": "slaap", "titel": "Windturbinegeluid verstoort de slaap", "sterkte": "Matig", "sterkte_uitleg": "Subjectieve slaapverstoring is consistent aangetoond; objectieve effecten zijn gevonden in een deel van de laboratoriumstudies en in een groot registeronderzoek bij ouderen.", "kern": "Omwonenden slapen aantoonbaar slechter. In het slaaplab veranderde de REM-slaap en reageren de hersenen al vanaf 33 dBA.", "steun": [{"id": 186, "punt": "Slaaplab (32 dB LAeq): langere REM-latentie, minder REM-slaap en slechter ervaren slaap."}, {"id": 167, "punt": "Windturbinegeluid verhoogde de kans op K-complexen (hersenreactie tijdens slaap) vanaf 33 dBA."}, {"id": 267, "punt": "Tijdens windturbinegeluid vaker ontwakingen, minder diepe slaap en meer subjectieve verstoring; de sterkte van amplitudemodulatie lijkt van belang (pilotstudies)."}, {"id": 215, "punt": "Deens register (584.000 volwassenen): bij ouderen hing veel nachtelijk windturbinegeluid samen met 68% meer gebruik van slaapmedicatie (HR 1,68)."}, {"id": 420, "punt": "Omwonenden op minder dan 1,4 km sliepen slechter, waren overdag slaperiger en hadden lagere mentale-gezondheidsscores."}, {"id": 301, "punt": "Japan: blootstelling boven 40 dB hing samen met meer slapeloosheid."}, {"id": 437, "punt": "Bewoners binnen 2 km rapporteerden slechtere slaapkwaliteit."}, {"id": 346, "punt": "Meta-analyse: hogere kans op slaapverstoring bij meer blootstelling."}, {"id": 1, "punt": "ICU-cohort (172 patiënten, polysomnografie): meer nachtelijk laagfrequent geluid hing samen met langere inslaaptijd, meer ontwakingen en minder diepe slaap en REM-slaap. Het laagfrequente deel was het luidste deel van het geluidsspectrum."}], "extern": [], "verweer": [{"claim": "Een meta-analyse vond geen effect op objectieve slaapmaten.", "studies": [158], "weerlegging": "De auteurs noemen zelf kleine steekproeven, variabele meetmethoden en kortdurende blootstelling. Het ontbreken van significant bewijs in kleine studies is geen bewijs van afwezigheid. Subjectieve slaapverstoring, die voor de gezondheid even relevant is, wordt wel consistent gevonden."}, {"claim": "Polysomnografie voor en na plaatsing liet geen verschil zien.", "studies": [289], "weerlegging": "Dezelfde studie vond wel een verslechterde ervaren slaapkwaliteit. Het ging om een kleine groep met kort meetmoment."}, {"claim": "Health Canada vond geen verband met objectief gemeten slaap.", "studies": [300, 179], "weerlegging": "In de actigrafie-analyse hingen variaties in het geluid wel samen met ontwakingen. Gemiddelde jaarwaarden maskeren juist de nachten met veel wind en modulatie."}], "tekst": "Er zijn concrete aanwijzingen dat windturbinegeluid de slaap verstoort. In een slaaplaboratorium leidde windturbinegeluid van slechts 32 dB LAeq tot een langere REM-latentie, minder REM-slaap en een slechter ervaren slaap (Smith et al., 2020). Hersenreacties tijdens de slaap traden op vanaf 33 dBA (Lechat et al., 2021). In een Deens registeronderzoek onder 584.000 volwassenen hing hoge nachtelijke blootstelling bij ouderen samen met een 68% hoger gebruik van slaapmedicatie (Poulsen et al., 2019). Omwonenden binnen 1,4 km sliepen slechter en waren overdag slaperiger (Nissenbaum et al., 2012). Dat juist het laagfrequente deel van geluid de slaapstructuur aantast, blijkt ook uit gemeten slaap (polysomnografie): meer nachtelijk laagfrequent geluid ging samen met langer wakker liggen, vaker ontwaken en minder diepe slaap en REM-slaap (Jin et al., 2026). Indiener verzoekt het bevoegd gezag te onderbouwen waarom deze effecten bij de geplande afstanden zijn uitgesloten.", "groep": "gezondheid"}, {"id": "hart", "titel": "Aanwijzingen voor effecten op hart en bloedvaten", "sterkte": "Indicatief", "sterkte_uitleg": "Een groot cohort en meerdere fysiologische studies tonen effecten; andere registerstudies vonden geen verband voor hartinfarct en beroerte.", "kern": "Langdurig windturbinegeluid hing samen met 30% meer boezemfibrilleren. Bij omwonenden daalt de hartslagvariabiliteit, en in het slaaplab reageren de bloedvaten op geluid.", "steun": [{"id": 220, "punt": "Deens verpleegkundigencohort (28.731 vrouwen): 30% hoger risico op boezemfibrilleren bij nachtelijk windturbinegeluid ≥20 dB(A) (HR 1,30)."}, {"id": 163, "punt": "Omwonenden binnen 500 m: hartslagvariabiliteit daalde significant bij meer laagfrequent windturbinegeluid."}, {"id": 135, "punt": "Tijdens de slaap lokte geluid (windturbine- en verkeersgeluid) vanaf 39 dBA een daling van de pulsgolfamplitude uit, een teken van vaatvernauwing."}, {"id": 291, "punt": "Korte blootstelling aan laagfrequent geluid verlaagde meerdere maten van hartslagvariabiliteit."}], "extern": [], "verweer": [{"claim": "Deense registerstudies vonden geen verband met hartinfarct, beroerte of diabetes.", "studies": [218, 249], "weerlegging": "Deze studies gebruiken gemodelleerde buitenniveaus in dB(A) en geen gemeten infrageluid. De auteurs melden zelf dat er weinig gevallen in de hoogste blootstellingsgroepen waren en dat replicatie nodig is."}], "tekst": "Er zijn aanwijzingen voor cardiovasculaire effecten. In een Deens cohort van 28.731 verpleegkundigen was langdurige nachtelijke blootstelling aan windturbinegeluid van ≥20 dB(A) geassocieerd met een 30% hoger risico op boezemfibrilleren (Bräuner et al., 2019). Bij omwonenden binnen 500 m daalde de hartslagvariabiliteit significant bij hogere blootstelling aan laagfrequent windturbinegeluid (Chiu et al., 2021), en tijdens de slaap lokte geluid vanaf 39 dBA vaatvernauwing uit (Lechat et al., 2022). Studies die geen verband vonden, melden zelf weinig gevallen in de hoogste blootstellingscategorieën (Poulsen et al., 2018). Indiener verzoekt deze risico's expliciet mee te wegen.", "groep": "gezondheid"}, {"id": "onhoorbaar", "titel": "Het lichaam reageert op infrageluid dat je niet hoort", "sterkte": "Matig", "sterkte_uitleg": "Gecontroleerde experimenten (o.a. met schijnblootstelling) tonen meetbare reacties van binnenoor en hersenen; de gezondheidsbetekenis op lange termijn is nog onvoldoende onderzocht.", "kern": "'Niet hoorbaar' betekent niet 'geen effect'. Het binnenoor en de hersenen reageren meetbaar op infrageluid onder de gehoordrempel.", "steun": [{"id": 456, "punt": "Het binnenoor (buitenste haarcellen) reageert op laagfrequent geluid en infrageluid, ook onder de gehoordrempel."}, {"id": 398, "punt": "Infrageluid van 5 Hz veroorzaakte grotere elektrische reacties in het binnenoor dan hogere tonen (proefdieren)."}, {"id": 308, "punt": "Na laagfrequent geluid verandert de versterkingsfunctie van de haarcellen in het menselijk oor meetbaar ('Bounce')."}, {"id": 271, "punt": "12 Hz infrageluid rond de gehoordrempel veranderde de connectiviteit in de hersenen (fMRI)."}, {"id": 87, "punt": "Gerandomiseerd onderzoek met schijnblootstelling: vier weken onhoorbaar 6 Hz infrageluid veranderde meerdere hersennetwerken; sommige veranderingen hingen samen met klachten en hinder."}], "extern": [], "verweer": [{"claim": "Proefpersonen konden infrageluid niet waarnemen en vertoonden geen autonome reacties.", "studies": [161], "weerlegging": "Niet kunnen waarnemen is iets anders dan geen fysiologische reactie. Deze labstudie gebruikte korte geluidsfragmenten; de hersenstudies met langere blootstelling tonen wel veranderingen."}, {"claim": "Infrageluid bij woningen ligt onder de gehoordrempel en is dus onschadelijk.", "studies": [333], "weerlegging": "Juist onderzoek naar het binnenoor en de hersenen laat zien dat reacties optreden onder de gehoordrempel. De gehoordrempel is daarom geen veilige grens."}], "tekst": "De aanname dat onhoorbaar infrageluid geen effect heeft, is wetenschappelijk niet houdbaar. Het binnenoor reageert op laagfrequent geluid en infrageluid ook onder de gehoordrempel (Salt & Hullar, 2010; Drexl et al., 2016). Infrageluid rond de gehoordrempel veranderde de connectiviteit in de hersenen (Weichenberger et al., 2017), en in een gerandomiseerd onderzoek met schijnblootstelling leidde vier weken onhoorbaar infrageluid tot veranderingen in meerdere hersennetwerken, deels samenhangend met klachten en hinder (Forlim et al., 2024). Indiener verzoekt het bevoegd gezag niet uit te gaan van de gehoordrempel als veilige grens.", "groep": "gezondheid"}, {"id": "stress", "titel": "Laagfrequent geluid verstoort het stresshormoon cortisol", "sterkte": "Indicatief", "sterkte_uitleg": "Gecontroleerde laboratoriumstudies tonen effecten op cortisol; klein aantal deelnemers.", "kern": "Nachtelijk laagfrequent geluid van 40 dB verstoorde het natuurlijke cortisolpatroon bij het ontwaken.", "steun": [{"id": 544, "punt": "Nachtelijk laagfrequent geluid (40 dB LAeq) verzwakte de cortisolrespons na ontwaken en verlengde de inslaaptijd."}, {"id": 559, "punt": "Laagfrequent geluid verzwakte de normale cortisoldaling bij deelnemers die sterk geluidgevoelig waren."}, {"id": 323, "punt": "Omwonenden in Ontario beschreven ernstige psychosociale stress rond windenergieprojecten."}, {"id": 217, "punt": "Laagfrequent geluid beïnvloedde fysiologische parameters negatief; bij verhoging van 50 naar 70 dB namen de effecten toe."}], "extern": [], "verweer": [{"claim": "In het slaaplab veranderde de cortisolrespons niet door windturbinegeluid.", "studies": [186], "weerlegging": "Dat betrof één interventienacht bij 32 dB. Chronische blootstelling over jaren is niet onderzocht."}], "tekst": "Laagfrequent geluid kan de stresshuishouding beïnvloeden. Nachtelijke blootstelling aan laagfrequent geluid van 40 dB LAeq verzwakte de cortisolrespons na het ontwaken en verlengde de inslaaptijd (Persson Waye et al., 2003); bij geluidgevoelige personen verstoorde laagfrequent geluid de normale cortisoldaling (Persson Waye et al., 2002). Indiener verzoekt deze effecten van chronische nachtelijke blootstelling te betrekken bij de beoordeling.", "groep": "gezondheid"}, {"id": "kwetsbaar", "titel": "Kwetsbare en gevoelige groepen lopen meer risico", "sterkte": "Matig", "sterkte_uitleg": "Meerdere studies tonen sterkere effecten bij ouderen en geluidgevoelige personen.", "kern": "Ouderen en geluidgevoelige mensen reageren sterker. Normen zijn gebaseerd op gemiddelden en beschermen deze groepen onvoldoende.", "steun": [{"id": 215, "punt": "Het verband met slaapmedicatie was het sterkst bij ouderen."}, {"id": 208, "punt": "Gevoeligheid voor infrageluid is meetbaar en hangt samen met lichamelijke en psychische klachten."}, {"id": 559, "punt": "De normale cortisoldaling was minder sterk bij geluidgevoelige deelnemers tijdens laagfrequent geluid."}, {"id": 568, "punt": "Laagfrequent geluid verslechterde sommige taakprestaties; de effecten waren sterker bij personen die gevoelig zijn voor laagfrequent geluid."}, {"id": 225, "punt": "Geluidsgevoeligheid hing samen met meer hinder door windturbinegeluid."}, {"id": 113, "punt": "Mensen die laagfrequent geluid waarnemen, rapporteren uiteenlopende klachten met vaak grote impact op het dagelijks leven."}, {"id": 1, "punt": "Bij ernstig zieke patiënten was meer nachtelijk laagfrequent geluid een onafhankelijke factor voor delier, mede via verstoorde slaap."}], "extern": [], "verweer": [{"claim": "Een dubbelblind onderzoek bij geluidgevoelige volwassenen vond geen effect.", "studies": [117], "weerlegging": "Die studie duurde 72 uur, had 37 deelnemers en werd voortijdig gestopt vanwege COVID-19-maatregelen. Ouderen, kinderen en mensen met bestaande klachten zijn niet onderzocht."}], "tekst": "Gevoelige groepen lopen een verhoogd risico. Het verband tussen nachtelijk windturbinegeluid en slaapmedicatie was het sterkst bij ouderen (Poulsen et al., 2019). Gevoeligheid voor infrageluid is meetbaar en hangt samen met lichamelijke en psychische klachten (Ascone et al., 2019), en effecten van laagfrequent geluid op cortisol en prestaties traden vooral op bij gevoelige personen (Persson Waye et al., 2001; 2002). Bij ernstig zieke patiënten was meer nachtelijk laagfrequent geluid zelfs een onafhankelijke risicofactor voor delier (Jin et al., 2026). Indiener verzoekt het bevoegd gezag te motiveren hoe kwetsbare bewoners in het plangebied worden beschermd.", "groep": "gezondheid"}, {"id": "langetermijn", "titel": "Langetermijneffecten van infrageluid zijn niet onderzocht", "sterkte": "Sterk", "sterkte_uitleg": "De belangrijkste studies zonder effect zijn kortdurend; dit wordt door de auteurs en reviews zelf erkend.", "kern": "De studies die 'geen effect' vinden, duurden 72 uur tot vier weken. Omwonenden worden twintig jaar of langer blootgesteld.", "steun": [{"id": 117, "punt": "Dubbelblinde studie met gesimuleerd windturbine-infrageluid: slechts 72 uur, voortijdig beëindigd door COVID-19-maatregelen."}, {"id": 157, "punt": "Pilotstudie van 28 nachten; verkennende afnames in grijze stof met onduidelijke betekenis."}, {"id": 87, "punt": "Vier weken blootstelling gaf al veranderingen in hersennetwerken."}, {"id": 302, "punt": "Systematische review: bewijs schaars, vooral voor chronische aandoeningen ('Is it time to listen?')."}, {"id": 212, "punt": "Scoping review: weinig studies naar klinische gezondheidsuitkomsten."}, {"id": 238, "punt": "Review van methodologische beperkingen en onzekerheden in de Health Canada-studie."}], "extern": [{"label": "Uppsala University: volgens Mattsson ontbreekt nog voldoende onderzoek naar de langetermijneffecten van infrageluid op de gezondheid", "url": "https://www.uu.se/en/department/information-technology/news/archive/2025-10-15-ken-mattsson-and-colleagues-at-uppsala-university-may-change-perceptions-of-wind-turbine-noise"}], "verweer": [{"claim": "Grote Deense registerstudies volgen mensen jarenlang en vinden geen effect.", "studies": [218, 249, 253], "weerlegging": "Deze studies meten geen infrageluid maar modelleren dB(A)-buitenniveaus, met weinig gevallen in de hoogste blootstellingsgroepen (zoals de auteurs zelf melden). Ze zeggen daarom weinig over langdurige infrageluidsblootstelling van moderne, grote turbines."}], "tekst": "De langetermijneffecten van infrageluid van moderne windturbines zijn niet onderzocht. De experimentele studies die geen effect vonden, duurden 72 uur (Marshall et al., 2023) of 28 nachten in een pilotopzet (Ascone et al., 2021), terwijl omwonenden twintig jaar of langer worden blootgesteld. Zelfs na vier weken werden al veranderingen in hersennetwerken gemeten (Forlim et al., 2024). Systematische reviews kwalificeren het bewijs als schaars, in het bijzonder voor chronische aandoeningen (Baliatsas et al., 2016; Freiberg et al., 2019). Het ontbreken van bewijs voor schade is daarmee geen bewijs van veiligheid. Indiener verzoekt het bevoegd gezag deze kennisleemte expliciet te benoemen en mee te wegen.", "groep": "gezondheid"}, {"id": "pulserend", "titel": "Laboratoriumgeluid is niet realistisch: windturbines pulseren", "sterkte": "Matig", "sterkte_uitleg": "Amplitudemodulatie verhoogt aantoonbaar hinder en slaapverstoring; veel experimenten gebruiken geen realistisch signaal.", "kern": "Het ritmisch 'zoevende' en pulserende karakter van windturbinegeluid maakt het hinderlijker en verstorender dan constant geluid.", "steun": [{"id": 311, "punt": "Amplitudegemoduleerd windturbinegeluid werd hinderlijker gevonden dan verkeersgeluid bij hetzelfde niveau."}, {"id": 296, "punt": "Een grotere modulatiediepte hing samen met meer hinder."}, {"id": 234, "punt": "Meer laagfrequente energie en sterkere amplitudemodulatie gaven meer hinder."}, {"id": 159, "punt": "Vaker waarneembare amplitudemodulatie hing samen met meer hinder; nachtelijke hinder hing samen met een lagere slaapefficiëntie."}, {"id": 267, "punt": "De pilotstudies suggereren dat de sterkte van amplitudemodulatie van belang is voor nadelige slaapeffecten."}, {"id": "G1746", "punt": "Binnenshuis was een door de bladpassage gemoduleerde laagfrequente toon 20% van de tijd hoorbaar tot 2,4 km en ’s nachts tot 22% van de tijd op 3,5 km."}, {"id": "G159", "punt": "Het pulserende karakter is ’s nachts sterker in een stabiele atmosfeer."}], "extern": [{"label": "Renew Economy: Mattsson stelt dat de Australische slaapstudie geen realistische, pulserende infrageluidsignalen gebruikte", "url": "https://reneweconomy.com.au/scientific-dead-end-the-new-push-to-get-wind-turbine-syndrome-back-on-the-radar/"}], "verweer": [{"claim": "Het experiment simuleerde het infrageluid van een windturbine.", "studies": [117], "weerlegging": "Volgens Mattsson zijn realistische, pulserende signalen niet gebruikt en zijn geen mensen met klachten onderzocht. Daarnaast toont de literatuur dat juist de modulatie de hinder en slaapverstoring verhoogt."}], "tekst": "Windturbinegeluid heeft een kenmerkend pulserend karakter (amplitudemodulatie). Onderzoek toont dat amplitudegemoduleerd windturbinegeluid bij hetzelfde geluidsniveau als hinderlijker wordt ervaren dan wegverkeersgeluid (Schäffer et al., 2016), dat een grotere modulatiediepte samenhangt met meer hinder (Ioannidou et al., 2016) en dat sterke modulatie bijdraagt aan slaapverstoring (Ageborg Morsing et al., 2018). Een jaar lang veldonderzoek bevestigt het verband met hinder (Hansen et al., 2021). Gemiddelde dB(A)-waarden doen geen recht aan dit karakter. Bij woningen tot 3,5 km van een windpark was ’s nachts binnenshuis een gemoduleerde laagfrequente toon tot 22% van de tijd hoorbaar (Hansen et al., 2019). Indiener verzoekt de effecten van amplitudemodulatie expliciet te beoordelen.", "groep": "gezondheid"}, {"id": "verspreiding", "titel": "De blootstelling aan infrageluid wordt onderschat", "sterkte": "Indicatief", "sterkte_uitleg": "Recent peer-reviewed modelonderzoek met veldvalidatie; nog geen onafhankelijke replicatie.", "kern": "Infrageluid van moderne turbines verspreidt zich verder en blijft sterker dan de gangbare rekenmodellen voorspellen.", "steun": [{"id": "M1", "punt": "Model (SoundSim360) gevalideerd met windturbinemetingen: infrageluid verspreidt zich verder dan gangbare modellen voorspellen."}, {"id": 278, "punt": "Deze studie betrof 3–5 MW-turbines; eerdere dosis-responsstudies betroffen turbines van 0,15–3,0 MW. Turbines worden steeds groter."}, {"id": "G39", "punt": "Infrageluid van een windpark met 60 turbines werd onder nachtelijke omstandigheden tot 90 km ver gemeten."}, {"id": "G14", "punt": "Pieken van 0,5–70 Hz waren tot 10 km van windturbines herkenbaar; voorbij 1 km konden ISO 9613-2-berekeningen onderschatten."}, {"id": "G1030", "punt": "Op 13 km over water bepalen de voortplantingsomstandigheden sterk hoeveel laagfrequent geluid van een offshore windpark aankomt."}], "extern": [{"label": "Uppsala University: SoundSim360 laat zien dat infrageluid van moderne windturbines aanzienlijk hoger is en verder reikt dan eerder aangenomen", "url": "https://www.uu.se/en/department/information-technology/news/archive/2025-11-27-it-department-in-the-media-the-issue-of-wind-turbine-noise-raised-in-the-eu---swedish-research-shows-that-infrasound-travels-further-than-previously-thought"}], "verweer": [{"claim": "Gemeten infrageluid binnenshuis ligt onder de gehoordrempel; laagfrequent geluid is boven 500 m vergelijkbaar met achtergrond.", "studies": [333], "weerlegging": "Metingen zijn momentopnames bij specifieke turbines en weersomstandigheden. Volgens recent onderzoek hangt verspreiding sterk af van atmosfeer en terrein en wordt deze door standaardmodellen onderschat. De gehoordrempel is bovendien geen veilige grens (zie argument 'Het lichaam reageert op infrageluid dat je niet hoort')."}], "tekst": "Recent peer-reviewed onderzoek van Uppsala University laat zien dat infrageluid van moderne windturbines zich verder verspreidt en hogere niveaus bereikt dan gangbare rekenmodellen voorspellen; het model is gevalideerd met metingen bij windturbines (Mattsson et al., 2026). Dit betekent dat de blootstelling van omwonenden in akoestisch onderzoek op basis van standaardmodellen kan worden onderschat. Ook ander onderzoek wijst op grote reikwijdte: infrageluid van een windpark werd ’s nachts tot 90 km ver gemeten (Marcillo et al., 2015), en voorbij 1 km kunnen gangbare berekeningen de lage tonen onderschatten (Keith et al., 2018). Indiener verzoekt het bevoegd gezag de infrageluidsblootstelling bij de dichtstbijzijnde woningen te laten berekenen met een model dat atmosferische omstandigheden en terrein meeneemt, en dit te laten verifiëren met metingen.", "groep": "gezondheid"}, {"id": "dba", "titel": "De dB(A)-norm onderschat laagfrequent geluid", "sterkte": "Matig", "sterkte_uitleg": "Al lang bekend in de akoestische literatuur; laagfrequent geluid is bij lage dB(A)-niveaus aantoonbaar hinderlijk.", "kern": "De A-weging telt lage tonen nauwelijks mee. Laagfrequent geluid kan daardoor zeer hinderlijk zijn terwijl de dB(A)-waarde laag lijkt.", "steun": [{"id": 532, "punt": "Review: hinder door laagfrequent geluid neemt snel toe met het niveau; A-gewogen metingen kunnen effecten onderschatten."}, {"id": 522, "punt": "Laagfrequent geluid in woningen kan ook bij lage A-gewogen niveaus als zeer hinderlijk worden ervaren."}, {"id": 514, "punt": "Laag-niveau laagfrequent geluid binnenshuis hing samen met meer hinder."}, {"id": 180, "punt": "Laagfrequente tonen verhoogden de ervaren hinder met tot 7 dB."}, {"id": 542, "punt": "Ruim tweemaal zoveel bewoners rapporteerden ernstige hinder binnenshuis van laagfrequent installatiegeluid als van verkeersgeluid."}, {"id": "G1148", "punt": "Bij hetzelfde dB(A)-niveau kan de ervaren luidheid sterk verschillen door de vorm van het spectrum; de A-weging alleen is daardoor een onvolledige maat."}, {"id": "G1156", "punt": "Op afstand blijft vooral laagfrequent geluid over; A-gewogen metingen geven dan niet het volledige hinderpotentieel weer."}, {"id": "G637", "punt": "Voor tonen van 20–200 Hz paste de C-weging beter dan de A-weging bij wat proefpersonen aanvaardbaar vonden."}], "extern": [], "verweer": [{"claim": "De norm in dB(A) of Lden is wettelijk voorgeschreven en voldoende.", "studies": [], "weerlegging": "Juridische toereikendheid is iets anders dan gezondheidskundige toereikendheid. Het bevoegd gezag moet bij een goede ruimtelijke ordening en een zorgvuldige belangenafweging ook rekening houden met effecten die de dB(A)-norm niet vangt."}], "tekst": "Toetsing aan uitsluitend A-gewogen geluidsniveaus onderschat de effecten van laagfrequent geluid. De A-weging telt lage frequenties nauwelijks mee, terwijl hinder door laagfrequent geluid snel toeneemt met het niveau (Leventhall, 2004) en laagfrequent geluid in woningen ook bij lage A-gewogen niveaus als zeer hinderlijk wordt ervaren (Findeis & Peters, 2004). Laagfrequente tonen verhogen de ervaren hinder met tot 7 dB (Yonemura et al., 2021). Bij hetzelfde dB(A)-niveau kan de ervaren luidheid sterk verschillen door de vorm van het spectrum (Salomons & Janssen, 2011). Indiener verzoekt het bevoegd gezag het laagfrequente en infrasone deel van het spectrum afzonderlijk te laten beoordelen, bijvoorbeeld in dB(C) of dB(G) en binnenshuis.", "groep": "gezondheid"}, {"id": "mechanisme", "titel": "Biologische mechanismen en dierstudies wijzen op schade", "sterkte": "Indicatief", "sterkte_uitleg": "Dierstudies gebruiken vaak hogere niveaus dan bij woningen; enkele studies laten effecten bij matige niveaus zien. Gebruik als ondersteunend argument.", "kern": "Dierproeven tonen schade aan evenwichtsorgaan, hart en nieren door laagfrequent geluid, deels al bij matige niveaus.", "steun": [{"id": 416, "punt": "Muizen: een maand 100 Hz-geluid van 70 dB SPL (matig niveau) gaf evenwichtsstoornissen en verlies van haarcellen in het evenwichtsorgaan."}, {"id": 189, "punt": "Ratten: infrageluid van hoge intensiteit verhoogde fibrose in de hartboezems."}, {"id": 9, "punt": "Muizen: dagelijkse blootstelling aan laagfrequent geluid veroorzaakte nierschade."}, {"id": 110, "punt": "Review: infrageluid kan via verstoorde mechanotransductie het endotheel en de microcirculatie aantasten (hypothese)."}, {"id": 496, "punt": "Review: vibroakoestische ziekte bij langdurig of excessief blootgestelde beroepsgroepen, met ook gevallen in de algemene bevolking; dosis-respons onduidelijk."}], "extern": [], "verweer": [{"claim": "Dierstudies gebruiken veel hogere niveaus dan bij woningen voorkomen.", "studies": [], "weerlegging": "Dat geldt voor een deel, maar niet voor alle studies: evenwichtsschade trad bij muizen al op bij 70 dB SPL. Dierstudies laten zien dat er biologische mechanismen bestaan; samen met de humane fysiologische studies maakt dat een effect bij langdurige blootstelling plausibel."}], "tekst": "Er bestaan biologisch plausibele mechanismen voor schade. Bij muizen leidde een maand blootstelling aan laagfrequent geluid van een matig niveau (70 dB SPL) tot evenwichtsstoornissen en verlies van haarcellen in het evenwichtsorgaan (Tamura et al., 2012). Ander dierexperimenteel onderzoek toont effecten op het hart (Lousinha et al., 2020) en de nieren (Kagawa et al., 2026). Deze bevindingen onderstrepen de noodzaak van voorzichtigheid bij langdurige blootstelling van omwonenden.", "groep": "gezondheid"}, {"id": "kwaliteit", "titel": "Lagere kwaliteit van leven bij omwonenden", "sterkte": "Indicatief", "sterkte_uitleg": "Meerdere vergelijkende en voor-nametingen tonen verslechtering; andere studies vinden geen gemiddeld effect.", "kern": "Omwonenden binnen enkele kilometers rapporteren een lagere kwaliteit van leven, minder rust en meer stress.", "steun": [{"id": 437, "punt": "Bewoners binnen 2 km: lagere algehele, fysieke en omgevingskwaliteit van leven."}, {"id": 263, "punt": "Woonafstand tot turbines hing samen met hinder en gezondheidsgerelateerde kwaliteit van leven."}, {"id": 292, "punt": "Voor- en nameting: na ingebruikname verslechterden mentale gezondheid en levenstevredenheid bij bewoners met hinder of zorgen."}, {"id": 25, "punt": "Duits panel 2002–2022: secundaire analyses wezen op mogelijk lagere mentale kwaliteit van leven bij hogere turbinedichtheid."}, {"id": 323, "punt": "Bij sommige bewoners aanzienlijke verslechtering van kwaliteit van leven en psychosociale stress."}], "extern": [], "verweer": [{"claim": "Er is gemiddeld geen effect op kwaliteit van leven.", "studies": [324, 25], "weerlegging": "Een gemiddelde over alle bewoners verbergt de groep die wel ernstig getroffen wordt. Ook deze studies vinden aanwijzingen voor effecten bij subgroepen."}], "tekst": "Onderzoek wijst op een lagere kwaliteit van leven bij omwonenden. Bewoners binnen 2 km van een windpark rapporteerden een lagere algehele, fysieke en omgevingskwaliteit van leven en een slechtere slaap (Shepherd et al., 2011), en woonafstand tot turbines hing samen met gezondheidsgerelateerde kwaliteit van leven (Barry et al., 2018). In een voor- en nametingsstudie verslechterden na ingebruikname de mentale gezondheid en levenstevredenheid bij bewoners met hinder of zorgen (Jalali et al., 2016). Indiener verzoekt het bevoegd gezag deze effecten te betrekken bij de belangenafweging.", "groep": "gezondheid"}, {"id": "voorzorg", "titel": "Wetenschappelijke onzekerheid vraagt om voorzorg", "sterkte": "Sterk", "sterkte_uitleg": "Reviews erkennen breed dat het bewijs schaars is en meer onderzoek nodig is; dat is een sterk procedureel argument.", "kern": "Reviews noemen het bewijs schaars en roepen op tot meer onderzoek. Zolang risico's niet zijn uitgesloten, hoort het bevoegd gezag voorzichtig te zijn.", "steun": [{"id": 302, "punt": "Systematische review: bewijs schaars; 'Is it time to listen?'"}, {"id": 363, "punt": "Alle geïncludeerde studies hadden selectie- en informatiebias; meer onderzoek nodig."}, {"id": 380, "punt": "Review: meldingen van symptomen en aanwijzingen voor fysiologische effecten van infrageluid op het oor; causaliteit nog onzeker."}, {"id": 184, "punt": "Nederlandstalige review: langdurige blootstelling aan windturbinegeluid, vooral 's nachts, hangt samen met slaapverstoring."}, {"id": 286, "punt": "Japanse review: herhaaldelijk verbanden tussen windturbinegeluid en subjectieve gezondheidseffecten, waaronder stress en slaap."}, {"id": 11, "punt": "Recente review: mogelijke schadelijke effecten van infrageluid bij hoge intensiteit of langdurige blootstelling."}], "extern": [{"label": "Uppsala University: onvoldoende onderzoek naar langetermijneffecten van infrageluid", "url": "https://www.uu.se/en/department/information-technology/news/archive/2025-10-15-ken-mattsson-and-colleagues-at-uppsala-university-may-change-perceptions-of-wind-turbine-noise"}], "verweer": [{"claim": "Reviews concluderen dat er geen bewijs is voor gezondheidseffecten van infrageluid.", "studies": [378, 371], "weerlegging": "Ook deze reviews erkennen het verband met hinder. 'Geen bewijs gevonden' in een beperkte en methodologisch zwakke literatuur betekent niet dat schade is uitgesloten. Juist dan is voorzorg op zijn plaats."}], "tekst": "De wetenschappelijke literatuur kenmerkt zich door grote onzekerheid. Systematische reviews kwalificeren het bewijs over gezondheidseffecten van laagfrequent geluid en infrageluid als schaars en methodologisch beperkt en roepen op tot meer onderzoek (Schmidt & Klokker, 2014; Baliatsas et al., 2016). Tegelijk bevatten reviews aanwijzingen voor slaapverstoring en fysiologische effecten (Farboud et al., 2013; de Laat et al., 2021). Waar ernstige of onomkeerbare gezondheidsschade niet kan worden uitgesloten, vraagt het voorzorgsbeginsel dat het bevoegd gezag terughoudend is, ruime afstanden hanteert of nader onderzoek laat uitvoeren voordat een besluit wordt genomen.", "groep": "gezondheid"}, {"id": "nocebo", "titel": "Klachten zijn niet af te doen als 'nocebo'", "sterkte": "Matig", "sterkte_uitleg": "Verwachtingen spelen een rol, maar blinde en registeronderzoeken tonen effecten waarbij verwachtingen geen rol kunnen spelen.", "kern": "Het 'het zit tussen de oren'-argument verklaart niet de objectief gemeten reacties in gecontroleerde experimenten en registeronderzoek.", "steun": [{"id": 87, "punt": "Gerandomiseerd onderzoek met schijnapparaten als controle: alleen bij echte infrageluidsblootstelling veranderden hersennetwerken."}, {"id": 271, "punt": "Objectief gemeten hersenreacties (fMRI) op infrageluid rond de gehoordrempel."}, {"id": 220, "punt": "Registeronderzoek met gemodelleerde blootstelling en objectieve uitkomst (ziekenhuisopname): meer boezemfibrilleren."}, {"id": 215, "punt": "Registeronderzoek: meer slaapmedicatie bij ouderen met hoge blootstelling."}, {"id": 167, "punt": "Objectief gemeten hersenreacties (K-complexen) tijdens de slaap."}], "extern": [], "verweer": [{"claim": "Laboratoriumstudies tonen dat negatieve verwachtingen klachten veroorzaken.", "studies": [354, 376, 332], "weerlegging": "Die experimenten waren kortdurend en met gezonde vrijwilligers. Ze laten zien dat verwachtingen klachten kunnen versterken, niet dat alle klachten daardoor ontstaan. Gecontroleerde experimenten en registeronderzoek tonen objectieve effecten."}, {"claim": "Anti-windbijeenkomsten veroorzaken de klachten.", "studies": [362], "weerlegging": "Die analyse onderzocht geen causaal effect op de gezondheid. Bovendien verklaart dit de objectieve effecten in gecontroleerde en registerstudies niet."}], "tekst": "Gezondheidsklachten van omwonenden zijn niet af te doen als uitsluitend een nocebo-effect. In een gerandomiseerd onderzoek met schijnapparaten als controle veranderden alleen bij echte blootstelling aan infrageluid meerdere hersennetwerken (Forlim et al., 2024). In registeronderzoek met gemodelleerde blootstelling en objectieve uitkomsten hing windturbinegeluid samen met boezemfibrilleren (Bräuner et al., 2019) en met het gebruik van slaapmedicatie door ouderen (Poulsen et al., 2019). Ook tijdens de slaap zijn objectieve hersenreacties gemeten (Lechat et al., 2021). Verwachtingen kunnen klachten versterken, maar verklaren deze objectief gemeten effecten niet.", "groep": "gezondheid"}, {"id": "keten", "groep": "blootstelling", "titel": "Redeneerketen: van turbine tot slaapkamer wordt laagfrequent geluid onderschat", "sterkte": "Matig", "sterkte_uitleg": "Elke schakel is met peer-reviewed onderzoek onderbouwd; de keten als geheel is een logische redenering, geen afzonderlijke studie.", "kern": "Grote turbines maken meer lage tonen, die dragen ver, worden ’s nachts sterker, dringen woningen binnen en worden door de dB(A)-norm nauwelijks meegeteld. Samen leidt dat tot onderschatting van wat omwonenden binnen ervaren.", "steun": [{"id": "G50", "punt": "Schakel 1 – bron: grote turbines (2,3–3,6 MW) stoten significant meer laagfrequent geluid uit dan kleinere; voor turbines rond 10 MW wordt een verdere verschuiving naar lage tonen verwacht."}, {"id": "G14", "punt": "Schakel 2 – verspreiding: pieken van 0,5–70 Hz waren tot 10 km van windturbines herkenbaar; voorbij 1 km konden berekeningen volgens ISO 9613-2 de niveaus onderschatten."}, {"id": "G723", "punt": "Schakel 3 – nacht: ’s nachts was de wind op ashoogte tot 2,6 keer sterker dan verwacht, met tot 15 dB hogere geluidsniveaus dan overdag bij dezelfde referentiewind."}, {"id": "G188", "punt": "Schakel 4 – woning: gesloten ramen dempten het geluid met 25,9 dB(A), maar slechts 15,3 dB(C); de lage tonen blijven dus binnen over."}, {"id": "G310", "punt": "Schakel 5 – kamer: door staande golven kan het niveau van lage tonen binnen een kamer 20–30 dB verschillen."}, {"id": "G1148", "punt": "Schakel 6 – norm: bij hetzelfde dB(A)-niveau kan de ervaren luidheid sterk verschillen door de vorm van het spectrum."}, {"id": "G454", "punt": "Schakel 7 – mens: individuele gehoordrempels verschillen tot 20 dB; wat voor de één onhoorbaar is, kan voor een ander luid of hinderlijk zijn."}, {"id": "G1746", "punt": "Uitkomst: bij woningen tot 3,5 km van een windpark was binnenshuis een gemoduleerde laagfrequente toon ’s nachts tot 22% van de tijd hoorbaar."}, {"id": 215, "punt": "Gezondheid: in een Deens registeronderzoek hing veel nachtelijk windturbinegeluid bij ouderen samen met meer gebruik van slaapmedicatie."}, {"id": "G47", "punt": "Laagfrequent geluid van 20–200 Hz kan bij woningen boven de gehoordrempel uitkomen; infrageluid kan via rammelende ramen merkbaar worden."}], "extern": [], "verweer": [{"claim": "Elke afzonderlijke schakel is klein; samen betekent het niets.", "studies": [], "weerlegging": "De schakels versterken elkaar. Meer lage tonen bij de bron, minder demping onderweg, hogere nachtniveaus, beperkte gevelwering en een meetmaat die lage tonen wegfiltert, wijzen allemaal dezelfde kant op. Het bevoegd gezag moet daarom het laagfrequente binnenniveau zelf beoordelen in plaats van te volstaan met een A-gewogen buitenwaarde."}, {"claim": "Infrageluid van windturbines ligt ver onder de gehoordrempel.", "studies": ["G4"], "weerlegging": "De keten gaat vooral over laagfrequent geluid van 20–200 Hz, dat bij woningen wel boven de gehoordrempel kan uitkomen (Doolan, 2013). Bovendien gaat ‘onder de drempel’ uit van de gemiddelde drempel, terwijl individuele drempels tot 20 dB verschillen (Rajala et al., 2022)."}], "tekst": "De beoordeling van het geluid onderschat wat omwonenden binnenshuis ervaren. Dat volgt uit een keten van peer-reviewed bevindingen. (1) Grote turbines stoten relatief meer laagfrequent geluid uit dan kleinere; het spectrum verschuift naar lagere tonen (Møller & Pedersen, 2011). (2) Lage tonen worden onderweg nauwelijks gedempt; pieken van 0,5–70 Hz waren tot 10 km herkenbaar en voorbij 1 km kunnen gangbare berekeningen de niveaus onderschatten (Keith et al., 2018). (3) ’s Nachts waait het op ashoogte veel harder dan bij de grond; in Nederlandse metingen leidde dat tot geluidsniveaus die tot 15 dB hoger waren dan overdag bij dezelfde referentiewind (Van den Berg, 2004). (4) De gevel dempt lage tonen veel minder dan hoge: in een meting in elf woningen 15,3 dB(C) tegenover 25,9 dB(A) (Keith et al., 2019). (5) In de kamer kunnen staande golven het niveau van lage tonen plaatselijk 20–30 dB laten verschillen (Pedersen et al., 2007). (6) De dB(A)-maat telt lage tonen nauwelijks mee, terwijl de ervaren luidheid bij gelijk dB(A)-niveau sterk kan verschillen (Salomons & Janssen, 2011). (7) Gehoordrempels verschillen tot 20 dB tussen mensen (Rajala et al., 2022). In de praktijk bleek een gemoduleerde laagfrequente toon binnenshuis op 3,5 km afstand ’s nachts tot 22% van de tijd hoorbaar (Hansen et al., 2019). Indiener verzoekt het bevoegd gezag het laagfrequente geluid binnenshuis afzonderlijk te beoordelen en daarbij uit te gaan van nachtelijke omstandigheden en gevoelige bewoners."}, {"id": "groot", "groep": "blootstelling", "titel": "Grotere turbines produceren meer laagfrequent geluid", "sterkte": "Matig", "sterkte_uitleg": "Consistente meetresultaten over tientallen turbines; recent bevestigd. Onderzoek naar de nieuwste generatie (6 MW en meer) is nog beperkt.", "kern": "Moderne grote turbines stoten relatief meer lage tonen uit dan de kleinere turbines waarop veel onderzoek en normen zijn gebaseerd.", "steun": [{"id": "G50", "punt": "Analyse van 48 turbines: grote turbines (2,3–3,6 MW) hebben significant meer laagfrequent geluid dan kleinere, overeenkomend met een verschuiving van het spectrum van ongeveer een derde octaaf. Door luchtabsorptie wordt het laagfrequente aandeel op woonafstand nog groter."}, {"id": "G57", "punt": "Een 4,5 MW-turbine produceerde bij dezelfde windsnelheid meer laagfrequent geluid dan een 1,5 MW-turbine."}], "extern": [], "verweer": [{"claim": "Door geluidsreducerende maatregelen zijn moderne turbines niet luider geworden.", "studies": ["G266"], "weerlegging": "Van den Berg et al. (2025) laten zien dat het totale geluidsvermogen boven 3 MW minder snel stijgt met de grootte. Dat zegt niets over de verdeling over de frequenties: Møller & Pedersen (2011) tonen juist een verschuiving naar lagere tonen. Indiener verzoekt aan te tonen dat het laagfrequente spectrum van het gekozen turbinetype is beoordeeld."}, {"claim": "Grotere turbines staan verder weg, waardoor het geluid bij woningen daalt.", "studies": ["G1357"], "weerlegging": "Hoen et al. (2023) komen tot lagere gemiddelde niveaus omdat grotere turbines grotere afstanden tot woningen en meer onderlinge ruimte vereisen. Dat voordeel bestaat alleen als de afstand ook werkelijk groter wordt. Laagfrequent geluid neemt bovendien minder af met de afstand dan hoog geluid (Møller & Pedersen, 2011)."}], "tekst": "De geplande turbines behoren tot de grootste generatie. Onderzoek naar 48 windturbines toont dat grote turbines significant meer laagfrequent geluid uitstoten dan kleinere, overeenkomend met een verschuiving van het spectrum met ongeveer een derde octaaf naar lagere tonen; voor turbines rond 10 MW verwachten de onderzoekers een verdere verschuiving (Møller & Pedersen, 2011). Doordat hoge tonen onderweg sterker door de lucht worden gedempt, wordt het laagfrequente aandeel bij woningen nog groter. Recente metingen bevestigen dat een 4,5 MW-turbine bij dezelfde windsnelheid meer laagfrequent geluid produceert dan een 1,5 MW-turbine (Wang et al., 2024). Veel gezondheidsonderzoek is uitgevoerd bij kleinere turbines. Indiener verzoekt het bevoegd gezag te onderbouwen dat de beoordeling rekening houdt met het laagfrequente spectrum van het gekozen turbinetype."}, {"id": "binnen", "groep": "blootstelling", "titel": "Lage tonen dringen woningen binnen; gevel en ramen beschermen minder", "sterkte": "Matig", "sterkte_uitleg": "Metingen en modelonderzoek wijzen eenduidig op beperkte gevelwering bij lage frequenties; onderzoek specifiek bij windturbinewoningen is beperkt in omvang.", "kern": "Gevels dempen lage tonen veel minder dan hoge. Binnen kunnen lage tonen door resonantie plaatselijk extra sterk zijn.", "steun": [{"id": "G188", "punt": "Metingen in 11 woningen: gesloten ramen dempten windturbinegeluid met 25,9 dB(A), maar met slechts 15,3 dB(C). Bij 35 dB(A) buiten was het geluid binnen hoorbaar tot 31,5 Hz; met een deels open raam voor 80–100% van de volwassenen onder 60 jaar."}, {"id": "G1746", "punt": "Binnenshuis was een gemoduleerde laagfrequente toon 20% van de tijd hoorbaar tot 2,4 km en 16% van de tijd op 3,5 km van een windpark."}, {"id": "G310", "punt": "Door staande golven kan het niveau van lage tonen binnen een kamer 20–30 dB variëren; de Deense meetmethode kan de luidste plekken flink onderschatten."}, {"id": "G1403", "punt": "Resonanties van bouwdelen en luchtlekken bepalen hoe laagfrequent geluid binnenkomt; trillende plafonds en wanden zijn de belangrijkste bron van laagfrequent binnengeluid."}, {"id": "G1317", "punt": "Ramen bepalen de geluidsoverdracht bij 15–30 Hz en muren bij 30–100 Hz; laagfrequent geluid binnen kan trillingen en geratel veroorzaken."}, {"id": "G361", "punt": "Ook bij gevels die aan bouwvoorschriften en geluidsrichtlijnen voldoen, kunnen lage tonen binnen hoorbaar zijn en de A-gewogen binnenniveaus domineren (onderzoek naar wegverkeer)."}], "extern": [], "verweer": [{"claim": "De gevel dempt het geluid met meer dan 20 dB, dus binnen is het stil.", "studies": ["G188"], "weerlegging": "Die demping geldt voor de A-gewogen totaalwaarde. In hetzelfde onderzoek was de C-gewogen demping, die lage tonen meeweegt, 15,3 dB en met open raam 9,9 dB. Met een deels open raam was het geluid voor 80–100% van de volwassenen onder 60 jaar hoorbaar (Keith et al., 2019)."}, {"claim": "Een meting binnenshuis liet geen overschrijding zien.", "studies": [], "weerlegging": "Door staande golven kan het niveau van lage tonen binnen één kamer 20–30 dB verschillen. Een meting op één punt kan de luidste plek missen (Pedersen et al., 2007)."}], "tekst": "De geluidsnorm wordt buiten aan de gevel getoetst, terwijl omwonenden binnen slapen. Juist lage tonen worden door gevels slecht tegengehouden. In metingen in elf woningen dempten gesloten ramen windturbinegeluid met 25,9 dB(A), maar met slechts 15,3 dB(C), de maat die lage tonen meeweegt; met een deels open raam was het geluid bij 35 dB(A) buiten voor 80–100% van de volwassenen onder 60 jaar hoorbaar (Keith et al., 2019). Bij woningen nabij een Australisch windpark was binnenshuis een gemoduleerde laagfrequente toon tot 3,5 km afstand regelmatig hoorbaar (Hansen et al., 2019). Binnen kunnen lage tonen door staande golven plaatselijk 20–30 dB sterker zijn (Pedersen et al., 2007), en trillende wanden en plafonds zijn een belangrijke bron van laagfrequent binnengeluid (Løvholt et al., 2011). Indiener verzoekt het bevoegd gezag het laagfrequente geluid binnenshuis te beoordelen, ook bij een geopend raam."}, {"id": "nacht", "groep": "blootstelling", "titel": "’s Nachts is het turbinegeluid hoger en sterker pulserend dan berekend", "sterkte": "Matig", "sterkte_uitleg": "Nederlandse veldmetingen en internationaal onderzoek bevestigen het mechanisme; de omvang verschilt per locatie en klimaat.", "kern": "In een stabiele nachtatmosfeer waait het op ashoogte veel harder dan bij de grond. Turbines maken dan meer en sterker pulserend geluid dan uit de wind bij de grond wordt afgeleid.", "steun": [{"id": "G723", "punt": "Nederlandse metingen: ’s nachts was de windsnelheid op ashoogte tot 2,6 keer hoger dan verwacht, met tot 15 dB hogere geluidsniveaus dan overdag bij dezelfde referentiewindsnelheid."}, {"id": "G156", "punt": "Atmosferische stabiliteit vergroot de windschering; de geluidsuitstoot is daardoor aanzienlijk hoger dan voorspeld op basis van de wind bij de grond en een neutrale atmosfeer, met een hogere geluidsbelasting bij woningen."}, {"id": "G159", "punt": "Het ritmische ‘zoeven’ is ’s nachts sterker in een stabiele atmosfeer; meerdere turbines kunnen dit effect volgens metingen verder versterken."}, {"id": "G39", "punt": "Onder nachtelijke omstandigheden werd infrageluid van een windpark tot 90 km ver gemeten; stabiele lucht versterkt volgens de auteurs ook de productie en modulatie van het geluid."}, {"id": "G1746", "punt": "’s Nachts was binnenshuis een gemoduleerde laagfrequente toon op 3,5 km afstand tot 22% van de tijd hoorbaar."}, {"id": "G155", "punt": "Modelonderzoek: de geluidsniveaus benedenwinds waren het hoogst bij matig stabiele omstandigheden, die in gematigde klimaten niet ongebruikelijk zijn."}], "extern": [], "verweer": [{"claim": "In stabiele omstandigheden kan het geluid juist lager zijn door afbuiging en schaduwzones.", "studies": ["G1074", "G131"], "weerlegging": "Deze Zweedse studies beschrijven specifieke situaties in een koud klimaat. Dezelfde onderzoeksgroep vond in schaduwzones juist vaker amplitudemodulatie (Bolin et al., 2020). Ander onderzoek vond de hoogste niveaus benedenwinds bij matig stabiele omstandigheden die in gematigde klimaten gangbaar zijn (Kelly et al., 2018), en Nederlandse metingen tot 15 dB meer geluid ’s nachts (Van den Berg, 2004)."}, {"claim": "De norm is een jaargemiddelde waarin de nacht al zwaarder meetelt.", "studies": [], "weerlegging": "Een jaargemiddelde middelt de nachten met veel en sterk pulserend geluid juist weg. Voor slaap tellen de afzonderlijke nachten. Indiener verzoekt inzicht in hoe vaak en hoeveel de nachtelijke niveaus boven het gemiddelde uitkomen."}], "tekst": "’s Nachts is de atmosfeer vaak stabiel: bij de grond is het nagenoeg windstil, terwijl het op ashoogte hard waait. Nederlandse metingen lieten zien dat de windsnelheid op ashoogte ’s nachts tot 2,6 keer hoger was dan verwacht, waardoor de turbines sneller draaiden en de geluidsniveaus tot 15 dB hoger waren dan overdag bij dezelfde referentiewind (Van den Berg, 2004). De geluidsuitstoot is in een stabiele atmosfeer aanzienlijk hoger dan voorspeld op basis van de wind bij de grond (Van den Berg, 2007), en het pulserende karakter wordt sterker (Van den Berg, 2005). Bij woningen tot 3,5 km van een windpark was ’s nachts binnenshuis een gemoduleerde laagfrequente toon tot 22% van de tijd hoorbaar (Hansen et al., 2019). Indiener verzoekt het bevoegd gezag te motiveren hoe in de geluidsberekening rekening is gehouden met stabiele nachtelijke omstandigheden en de daarbij optredende pulsering."}, {"id": "rekenmodel", "groep": "blootstelling", "titel": "De geluidsberekening is onzeker voor lage tonen en grotere afstanden", "sterkte": "Matig", "sterkte_uitleg": "Meerdere validatiestudies wijzen op onzekerheid voor lage frequenties en grote afstanden. Eerlijk is: voor A-gewogen geluid dichtbij zijn modellen redelijk nauwkeurig, en sommige auteurs noemen ISO 9613-2 bruikbaar als eerste screening.", "kern": "Gangbare rekenmodellen zijn ontwikkeld en gevalideerd voor A-gewogen geluid op korte afstand. Voor lage tonen, grote afstanden, heuvels en wake-effecten zijn ze onzeker.", "steun": [{"id": "G14", "punt": "Bij metingen voor het Health Canada-onderzoek waren pieken van 0,5–70 Hz tot 10 km herkenbaar; voorbij 1 km konden berekeningen volgens ISO 9613-2 de niveaus onderschatten."}, {"id": "G34", "punt": "Voor infrageluid en laagfrequent geluid zijn gangbare rekenmodellen volgens de auteurs doorgaans niet gevalideerd. In de vergelijking met metingen gaf Nord2000 nauwkeurige resultaten; ISO 9613-2 vonden de auteurs alleen geschikt voor vereenvoudigde beoordelingen."}, {"id": "G95", "punt": "Voorspellingen volgens ISO 9613-2 weken tot 56,5 dB(Z) (mediaan 29,6 dB(Z)) af van metingen bij een operationeel windpark."}, {"id": "G1030", "punt": "Op 13 km over water bepaalden de voortplantingsomstandigheden sterk hoeveel laagfrequent geluid aankwam; gewone beoordelingsmethoden kunnen op grote afstand onnauwkeurig worden."}, {"id": "G227", "punt": "De wake van een turbine bevordert de voortplanting van geluid van de bladtippen naar de grond; de berekende geluidsimpact is gevoelig voor de gekozen meteorologie."}, {"id": "G289", "punt": "Wereldwijd leiden windparken die aan de vergunningsvoorwaarden voldoen toch tot klachten; naleving is moeilijk aan te tonen omdat achtergrondgeluid de bijdrage van de turbines maskeert."}], "extern": [], "verweer": [{"claim": "Het gebruikte rekenmodel is gevalideerd en nauwkeurig.", "studies": ["G218", "G214"], "weerlegging": "Die validaties betreffen vooral A-gewogen niveaus bij benedenwindse omstandigheden over vlak terrein, tot ongeveer 1,5 km. Voor lage frequenties en grotere afstanden noemen andere studies de modellen niet gevalideerd (Stępień et al., 2024) en kan ISO 9613-2 onderschatten (Keith et al., 2018). Indiener verzoekt te motiveren welk model is gebruikt en of het voor lage frequenties is gevalideerd."}], "tekst": "De geluidsberekening in het besluit is onzeker voor juist het geluid waar omwonenden het meest last van hebben. Gangbare rekenmodellen zijn voor infrageluid en laagfrequent geluid doorgaans niet gevalideerd; in een vergelijking met metingen gaf alleen het uitgebreidere Nord2000-model nauwkeurige resultaten, terwijl ISO 9613-2 slechts geschikt werd geacht voor vereenvoudigde beoordelingen (Stępień et al., 2024). Bij metingen voor het Health Canada-onderzoek waren pieken van 0,5–70 Hz tot 10 km herkenbaar en konden berekeningen volgens ISO 9613-2 voorbij 1 km de niveaus onderschatten (Keith et al., 2018). Bij een operationeel windpark weken ISO 9613-2-voorspellingen tot 56,5 dB(Z) af van metingen (Echeverri Londoño & González, 2018). Ook de wake van turbines en de meteorologie beïnvloeden sterk hoeveel geluid de grond bereikt (Heimann et al., 2011). Tot slot blijkt in de praktijk dat windparken die aan de vergunningsvoorwaarden voldoen toch tot klachten leiden (Cooper & Chan, 2020). Indiener verzoekt het bevoegd gezag te motiveren welk rekenmodel is gebruikt, of dat model voor lage frequenties en de gekozen turbinehoogte is gevalideerd, en welke onzekerheidsmarge is gehanteerd."}, {"id": "drempel", "groep": "blootstelling", "titel": "De gehoordrempel is een gemiddelde: veel mensen horen of voelen lage tonen eerder", "sterkte": "Matig", "sterkte_uitleg": "Laboratoriumonderzoek toont consistent grote individuele verschillen; de groepen proefpersonen zijn klein.", "kern": "‘Onder de gehoordrempel’ gaat uit van een gemiddelde. Individuele drempels verschillen tot 20 dB, en mensen met klachten over laagfrequent geluid hebben een smallere marge.", "steun": [{"id": "G454", "punt": "Individuele gehoordrempels verschilden tot 20 dB; een infratoon die voor de één onhoorbaar is, kan voor een ander luid of hinderlijk zijn. Bij 4 Hz voelt 5 dB meer als 10 dB bij 20 Hz en als 20 dB bij 1 kHz."}, {"id": "G1759", "punt": "De gehoordrempels voor lage tonen zijn tussen gezonde mensen normaal verdeeld; volgens de auteurs moet die spreiding worden meegenomen bij de beoordeling van de hoorbaarheid van laagfrequent geluid."}, {"id": "G531", "punt": "Mensen met klachten over laagfrequent geluid legden hun grens van aanvaardbaarheid dichter bij hun gehoordrempel; voor fluctuerende geluiden lag die grens gemiddeld 5 dB lager."}, {"id": "G456", "punt": "Infrageluid boven de waarnemingsdrempel maskeerde lage tonen van 64 Hz en beïnvloedde de waarneming van amplitudemodulatie."}, {"id": "G459", "punt": "Combinaties van infrageluid en hoorbaar geluid werden even onaangenaam of onaangenamer gevonden dan elk geluid afzonderlijk."}, {"id": "G188", "punt": "Bij 35 dB(A) buiten was windturbinegeluid binnen met een deels open raam hoorbaar voor 80–100% van de volwassenen onder 60 jaar."}, {"id": "G47", "punt": "Review: laagfrequent geluid van 20–200 Hz kan bij woningen boven de gehoordrempel uitkomen; veel klachten over windturbines lijken op klachten over laagfrequent geluid in het algemeen."}], "extern": [], "verweer": [{"claim": "Infrageluid van windturbines ligt ver onder de gehoordrempel en kan dus geen effect hebben.", "studies": ["G4", "G8"], "weerlegging": "Die conclusie gaat uit van de gemiddelde drempel van gezonde proefpersonen. Individuele drempels verschillen tot 20 dB (Rajala et al., 2022). Bovendien gaat het niet alleen om infrageluid: laagfrequent geluid van 20–200 Hz kan bij woningen wel boven de gehoordrempel uitkomen (Doolan, 2013), en infrageluid beïnvloedt hoe lage tonen en pulsering worden waargenomen (Friedrich et al., 2023)."}], "tekst": "Het argument dat laagfrequent geluid en infrageluid ‘onder de gehoordrempel’ blijven, gaat uit van een gemiddelde mens. Individuele gehoordrempels verschillen tot 20 dB, zodat een toon die voor de één onhoorbaar is voor een ander luid of hinderlijk kan zijn (Rajala et al., 2022). De drempels zijn normaal verdeeld en die spreiding hoort volgens onderzoekers bij de beoordeling te worden betrokken (Kurakata & Mizunami, 2008). Mensen met klachten over laagfrequent geluid leggen hun grens van aanvaardbaarheid dichter bij hun gehoordrempel, en voor fluctuerend geluid ligt die grens gemiddeld 5 dB lager (Moorhouse et al., 2007). Bovendien beïnvloedt infrageluid de waarneming van lage tonen en pulsering (Friedrich et al., 2023). Indiener verzoekt het bevoegd gezag uit te gaan van gevoelige bewoners en niet van de gemiddelde gehoordrempel."}, {"id": "lfnnorm", "groep": "blootstelling", "titel": "Een aparte toets voor laagfrequent geluid binnenshuis is mogelijk en gebruikelijk", "sterkte": "Matig", "sterkte_uitleg": "Denemarken hanteert sinds 2012 een wettelijke binnenwaarde voor laagfrequent windturbinegeluid; dit is een bestaand en peer-reviewed beschreven precedent.", "kern": "Denemarken toetst windturbines sinds 2012 aan een aparte grenswaarde voor laagfrequent geluid binnenshuis. Een vergelijkbare toets ontbreekt in veel beoordelingen.", "steun": [{"id": "G51", "punt": "De Deense regelgeving bevat sinds 1 januari 2012 een verplichte grenswaarde voor laagfrequent windturbinegeluid van 20 dB, A-gewogen berekend binnenniveau in de tertsbanden 10–160 Hz, om hinder door laagfrequent geluid te voorkomen."}, {"id": "G1156", "punt": "Omdat hoge tonen op afstand sterker worden gedempt, blijft bij woningen vooral laagfrequent geluid over; A-gewogen metingen geven dan niet het volledige hinderpotentieel weer."}, {"id": "G637", "punt": "De aanvaardbaarheidsgrens voor tonen van 20–200 Hz kwam ongeveer overeen met de C-weging; de C-weging bleek beter geschikt dan de A-weging voor de beoordeling van lage frequenties."}, {"id": "G188", "punt": "Gesloten ramen dempten windturbinegeluid met 25,9 dB(A), maar slechts 15,3 dB(C): een buitenwaarde in dB(A) zegt weinig over de lage tonen binnen."}], "extern": [], "verweer": [{"claim": "De Nederlandse normen zijn voldoende; een aparte toets voor laagfrequent geluid is niet nodig.", "studies": [], "weerlegging": "Een A-gewogen buitenwaarde geeft het laagfrequente binnengeluid onvoldoende weer (DeGagne & Lapka, 2008; Keith et al., 2019). Denemarken laat zien dat een aparte toets uitvoerbaar is (Jakobsen, 2012). Indiener verzoekt te motiveren waarom een vergelijkbare toets hier achterwege kan blijven."}], "tekst": "Het is mogelijk en gebruikelijk om laagfrequent windturbinegeluid afzonderlijk te beoordelen. Denemarken hanteert sinds 1 januari 2012 een verplichte grenswaarde van 20 dB voor het berekende, A-gewogen binnenniveau in de tertsbanden van 10 tot 160 Hz, met als doel hinder door laagfrequent geluid te voorkomen (Jakobsen, 2012). Een aparte toets is nodig, omdat op afstand vooral het laagfrequente deel van het geluid overblijft en A-gewogen metingen het hinderpotentieel dan niet volledig weergeven (DeGagne & Lapka, 2008). Voor de beoordeling van lage tonen blijkt de C-weging beter te passen bij wat mensen aanvaardbaar vinden (Hong, 2007). Indiener verzoekt het bevoegd gezag het laagfrequente geluid binnenshuis bij de dichtstbijzijnde woningen te laten berekenen en te toetsen aan een binnenwaarde zoals de Deense, of te motiveren waarom dat niet nodig is."}, {"id": "tonen", "groep": "blootstelling", "titel": "Windturbines maken hoorbare lage tonen die de hinder vergroten", "sterkte": "Indicatief", "sterkte_uitleg": "Meerdere metingen vinden hoorbare tonen; onderzoek naar de frequentie bij woningen is beperkt.", "kern": "Generator en aandrijving produceren lage tonen die door de draaiende bladen ritmisch worden gemoduleerd. Tonaal en pulserend geluid is hinderlijker dan breedbandig geluid.", "steun": [{"id": "G113", "punt": "Bij een Duits windpark kwam amplitudemodulatie voort uit tonen van 57,8 en 133 Hz van generator en aandrijving, gemoduleerd door de bladpassagefrequentie."}, {"id": "G54", "punt": "Bij een 1,5 MW-turbine werden drie tonen onder 100 Hz vastgesteld; de toon rond 78 Hz lag boven de gehoordrempel."}, {"id": "G878", "punt": "Bij toepassing van de IEC 61400-11-methode werden in alle onderzochte spectra hoorbare tonen gevonden."}, {"id": "G1746", "punt": "Binnenshuis was een hoorbare laagfrequente toon, gemoduleerd door de bladpassage, tot 3,5 km van een windpark regelmatig aanwezig."}], "extern": [], "verweer": [{"claim": "Bij moderne turbines verdwijnen tonen in breedbandig geluid.", "studies": ["G66"], "weerlegging": "Lee & Cheong (2014) beschrijven dat de tonen bij de bladpassagefrequentie bij grote turbines vervagen. Dat gaat over het infrageluid van de bladen. Metingen vinden wel tonen uit generator en aandrijving, zoals 57,8 en 133 Hz (Blumendeller et al., 2023), en een toon rond 78 Hz boven de gehoordrempel (Son et al., 2018)."}], "tekst": "Windturbines produceren naast breedbandig geluid ook lage tonen. Bij een Duits windpark kwamen tonen van 57,8 en 133 Hz uit generator en aandrijving voor, die door de draaiende bladen ritmisch werden gemoduleerd (Blumendeller et al., 2023). Bij een 1,5 MW-turbine lag een toon rond 78 Hz boven de gehoordrempel (Son et al., 2018). Binnenshuis was een gemoduleerde laagfrequente toon tot 3,5 km van een windpark regelmatig hoorbaar (Hansen et al., 2019). Indiener verzoekt het bevoegd gezag te motiveren hoe tonale componenten en hun modulatie in de beoordeling zijn meegenomen."}, {"id": "trilling", "groep": "blootstelling", "titel": "Turbines veroorzaken laagfrequente trillingen die ver reiken", "sterkte": "Indicatief", "sterkte_uitleg": "Trillingen van turbines zijn meetbaar tot op grote afstand; onderzoek naar de gevolgen in woningen is schaars en steunt deels op andere bronnen.", "kern": "Windturbines brengen de bodem en gebouwen in laagfrequente trilling. Trilling en geluid samen geven meer hinder en slaapverstoring dan geluid alleen.", "steun": [{"id": "G259", "punt": "Bij twee Duitse windparken veroorzaakten de turbines seismische trillingen in banden tussen 2,2 en 6,6 Hz, waarvan de sterkte toenam met de windsnelheid en de rotatiesnelheid."}, {"id": "G0", "punt": "De review stelt dat windturbine-infrageluid voelbare trillingen en hoorbaar geluid in nabijgelegen gebouwen veroorzaakt."}, {"id": "G1317", "punt": "Laagfrequent geluid dat een gebouw binnenkomt, veroorzaakt trillingen en geratel die tot hinder kunnen leiden."}, {"id": "G1426", "punt": "De totale hinder van gelijktijdig geluid en trilling was aanzienlijk groter dan die van geluid alleen (onderzoek naar treinen)."}, {"id": "G1455", "punt": "Trilling alleen verhoogde al de kans op ontwaken tijdens de slaap; de effecten van trilling en geluid telden op (onderzoek naar goederentreinen)."}], "extern": [], "verweer": [{"claim": "Trillingen van windturbines zijn te zwak om te voelen.", "studies": [], "weerlegging": "Er is weinig onderzoek naar trillingen in woningen bij windturbines. Wel blijkt dat laagfrequent geluid bouwdelen laat meetrillen (Løvholt et al., 2017) en dat trilling en geluid samen meer hinder en slaapverstoring geven dan geluid alleen (Lee & Griffin, 2013; Smith et al., 2017). Indiener verzoekt dit aspect te laten onderzoeken."}], "tekst": "Windturbines veroorzaken niet alleen geluid maar ook laagfrequente trillingen. Bij twee Duitse windparken waren seismische trillingen tussen 2,2 en 6,6 Hz meetbaar, die sterker werden naarmate het harder waaide en de rotor sneller draaide (Flores Estrella et al., 2017). Laagfrequent geluid dat een woning binnenkomt, kan bouwdelen laten trillen en ratelen (Løvholt et al., 2017). Uit onderzoek naar treinen blijkt dat trilling en geluid samen aanzienlijk meer hinder geven dan geluid alleen (Lee & Griffin, 2013) en dat trilling alleen al de kans op ontwaken verhoogt (Smith et al., 2017). Indiener verzoekt het bevoegd gezag de gevolgen van trillingen en door geluid opgewekte trillingen in woningen te laten onderzoeken."}, {"id": "samenloop", "groep": "blootstelling", "titel": "Opstelling, terrein en samenloop met andere turbines versterken het geluid", "sterkte": "Indicatief", "sterkte_uitleg": "Vooral gebaseerd op simulaties en metingen bij afzonderlijke parken; praktijkonderzoek naar samenloop is beperkt.", "kern": "Turbines die achter elkaar of op hoger terrein staan, kunnen het geluid en de pulsering benedenwinds met enkele decibels verhogen.", "steun": [{"id": "G103", "punt": "Staat een turbine direct achter een andere, dan verhoogt de wake het geluidsniveau en de amplitudemodulatie benedenwinds met enkele decibel."}, {"id": "G148", "punt": "De stroming in een windpark verandert waar het geluid wordt versterkt; een versprongen opstelling produceert in totaal meer geluid."}, {"id": "G124", "punt": "Een turbine op een heuveltop verhoogde in simulaties het gemiddelde geluidsniveau en de amplitudemodulatie benedenwinds."}, {"id": "G159", "punt": "Metingen lieten zien dat extra turbines het pulserende karakter verder kunnen versterken."}], "extern": [], "verweer": [{"claim": "Het geluid van meerdere turbines telt maar beperkt op.", "studies": [], "weerlegging": "Simulaties laten zien dat turbines achter elkaar door wake-focussering het geluid en de pulsering benedenwinds met enkele decibel verhogen (Colas et al., 2026). Indiener verzoekt de opstelling, het terrein en andere windparken in de omgeving in de berekening te betrekken."}], "tekst": "Het geluid van een windpark is meer dan de optelsom van losse turbines. Staat een turbine direct achter een andere, dan verhoogt de wake het geluidsniveau en de pulsering benedenwinds met enkele decibel (Colas et al., 2026). Een turbine op een heuveltop verhoogde in simulaties het gemiddelde geluidsniveau en de amplitudemodulatie benedenwinds (Colas et al., 2024), en extra turbines kunnen het pulserende karakter versterken (Van den Berg, 2005). Indiener verzoekt het bevoegd gezag te motiveren hoe de opstelling, het terrein en samenloop met andere windparken in de geluidsberekening zijn meegenomen."}];
window.VERWEER=[{"ids": [117], "naam": "Marshall et al. (2023) – 72 uur infrageluid in slaaplab", "wat": "37 geluidgevoelige, verder gezonde volwassenen kregen in een slaaplab 72 uur gesimuleerd windturbine-infrageluid (1,6–20 Hz, circa 90 dB piek), schijnblootstelling en verkeersgeluid.", "bevinding": "Infrageluid had geen meetbaar effect op wakker liggen na inslapen of andere gemeten uitkomsten; verkeersgeluid wel.", "zwakten": ["Blootstelling van slechts 72 uur; omwonenden worden jarenlang blootgesteld.", "De studie werd voortijdig beëindigd door COVID-19-maatregelen.", "Gezonde deelnemers; geen mensen met bestaande klachten, ouderen of kinderen.", "Volgens Mattsson geen realistische, pulserende infrageluidsignalen."], "weerwoord": "Deze studie zegt iets over 72 uur blootstelling bij gezonde volwassenen, niet over jarenlange blootstelling van omwonenden. De onderzoekers moesten de studie bovendien voortijdig stoppen. De conclusie 'infrageluid is onschadelijk' gaat daarom verder dan de studie draagt.", "extern": {"label": "Renew Economy – reactie Mattsson", "url": "https://reneweconomy.com.au/scientific-dead-end-the-new-push-to-get-wind-turbine-syndrome-back-on-the-radar/"}}, {"ids": [300, 230], "naam": "Michaud et al. (2016) – Health Canada-studie", "wat": "Cross-sectionele studie bij 1.238 deelnemers rond Canadese windparken, met berekende geluidsniveaus tot 46 dBA en deels objectieve metingen.", "bevinding": "Meer windturbinegeluid hing samen met meer hinder, maar niet met de onderzochte klachten, slaapuitkomsten of kwaliteit van leven.", "zwakten": ["Cross-sectioneel: zegt niets over oorzaak en gevolg of langetermijneffecten.", "Gebaseerd op berekende dB(A)-niveaus, niet op gemeten infrageluid.", "Methodologische kritiek in de literatuur (Krogh et al., 2018).", "In de actigrafie-analyse hingen variaties in geluid wel samen met ontwakingen."], "weerwoord": "Ook de Health Canada-studie bevestigt een duidelijk verband tussen windturbinegeluid en hinder, en de WHO erkent hinder als gezondheidseffect. Voor de overige uitkomsten is de studie met haar cross-sectionele opzet en dB(A)-maat niet geschikt om effecten van infrageluid op lange termijn uit te sluiten.", "refs_extra": [238, 179]}, {"ids": [218, 249, 253], "naam": "Poulsen et al. (2018–2019) – Deense registerstudies", "wat": "Landelijke registerstudies met gemodelleerd nachtelijk windturbinegeluid bij woningen en gegevens over hartinfarct, beroerte, diabetes en zwangerschapsuitkomsten.", "bevinding": "Geen overtuigend verband met hartinfarct, beroerte, diabetes of ongunstige geboorte-uitkomsten.", "zwakten": ["Gemodelleerde buitenniveaus in dB(A); geen gemeten infrageluid.", "De auteurs melden zelf weinig gevallen in de hoogste blootstellingsgroepen en roepen op tot replicatie.", "Dezelfde onderzoeksgroep vond wel meer slaapmedicatie en antidepressiva bij ouderen (Poulsen et al., 2019) en een ander Deens cohort meer boezemfibrilleren (Bräuner et al., 2019)."], "weerwoord": "Deze studies kunnen effecten bij hoge blootstelling nauwelijks beoordelen, omdat daar weinig gevallen waren. Bovendien vond onderzoek met dezelfde Deense gegevens wel verbanden met slaapmedicatie bij ouderen en met boezemfibrilleren.", "refs_extra": [215, 220]}, {"ids": [158], "naam": "Liebich et al. (2021) – meta-analyse slaap", "wat": "Systematische review en meta-analyse van studies naar windturbinegeluid en objectief en subjectief gemeten slaap.", "bevinding": "Geen significante effecten op belangrijke objectieve slaapindicatoren.", "zwakten": ["De auteurs noemen zelf kleine steekproeven en variabele meetmethoden.", "Veel studies met korte blootstelling.", "Subjectieve slaapverstoring wordt in andere reviews wel consistent gevonden."], "weerwoord": "Een niet-significant resultaat in een kleine, heterogene set studies is geen bewijs dat er geen effect is. Andere studies tonen wel veranderingen in REM-slaap en hersenreacties tijdens de slaap vanaf 33 dBA.", "refs_extra": [186, 167, 346]}, {"ids": [161], "naam": "Maijala et al. (2021) – Finse labstudie infrageluid", "wat": "Laboratoriumexperiment met geluidsfragmenten van windturbines, met en zonder infrageluid, bij mensen met en zonder klachten die zij aan infrageluid toeschrijven.", "bevinding": "Deelnemers konden het infrageluid niet waarnemen; infrageluid beïnvloedde hinder en hartslag niet.", "zwakten": ["Korte blootstelling aan fragmenten in een lab.", "Niet waarnemen is iets anders dan geen fysiologische reactie.", "Langere blootstelling gaf in hersenonderzoek wel veranderingen."], "weerwoord": "Dat mensen infrageluid niet bewust waarnemen, betekent niet dat het lichaam er niet op reageert. Studies naar binnenoor en hersenen tonen reacties onder de gehoordrempel.", "refs_extra": [456, 271, 87]}, {"ids": [157], "naam": "Ascone et al. (2021) – 28 nachten infrageluid", "wat": "Gerandomiseerde pilotstudie: gezonde deelnemers sliepen 28 nachten bij 6 Hz infrageluid (80–90 dB) of schijnblootstelling.", "bevinding": "Geen significante veranderingen in gedrag, klachten, slaap of cognitie; verkennende afnames in grijze stof met onduidelijke betekenis.", "zwakten": ["Pilotstudie met een kleine groep.", "Gezonde deelnemers.", "Vervolganalyse (Forlim et al., 2024) vond wel veranderingen in hersennetwerken, deels samenhangend met klachten en hinder."], "weerwoord": "Juist deze onderzoeksgroep vond in de vervolganalyse veranderingen in hersennetwerken na vier weken. Het is daarom onjuist deze studie te presenteren als bewijs dat infrageluid geen effect heeft.", "refs_extra": [87]}, {"ids": [354, 376, 332], "naam": "Crichton et al. (2014–2015) – nocebo-experimenten", "wat": "Korte laboratoriumexperimenten waarin deelnemers vooraf positieve of negatieve informatie kregen over infrageluid.", "bevinding": "Wie negatieve verwachtingen had, meldde meer klachten, ook bij schijnblootstelling.", "zwakten": ["Zeer korte blootstelling.", "Gezonde vrijwilligers, geen omwonenden.", "Toont dat verwachtingen klachten kunnen versterken, niet dat alle klachten daardoor ontstaan."], "weerwoord": "Objectief gemeten effecten in gecontroleerde experimenten en registeronderzoek zijn niet met verwachtingen te verklaren.", "refs_extra": [87, 220, 167]}, {"ids": [333], "naam": "Berger et al. (2015) – metingen infrageluid binnenshuis", "wat": "Metingen van infrageluid en laagfrequent geluid binnen en buiten woningen op 400–900 m van windturbines.", "bevinding": "Infrageluid binnenshuis lag onder de gehoordrempel; laagfrequent geluid was boven 500 m vergelijkbaar met achtergrondniveaus.", "zwakten": ["Momentopname bij specifieke turbines en weersomstandigheden.", "De gehoordrempel is geen veilige grens: het lichaam reageert ook onder die drempel.", "Recent onderzoek toont dat standaardmodellen de verspreiding van infrageluid onderschatten."], "weerwoord": "Of infrageluid hoorbaar is, is niet de juiste maatstaf. Daarnaast wijst recent peer-reviewed onderzoek erop dat infrageluid van moderne turbines verder reikt dan aangenomen.", "refs_extra": [456, "M1"]}, {"ids": [22], "naam": "Lechat et al. (2026) – windturbine- versus verkeersgeluid tijdens slaap", "wat": "Slaaplabstudie die korte geluidsfragmenten van windparken en wegverkeer vergeleek bij gelijke niveaus.", "bevinding": "Windturbinegeluid gaf iets minder EEG-arousals en ontwakingen dan verkeersgeluid.", "zwakten": ["Vergelijking met verkeersgeluid zegt niet dat windturbinegeluid onschadelijk is.", "Korte fragmenten; geen nachtenlange blootstelling.", "Dezelfde groep vond hersen- en vaatreacties tijdens de slaap vanaf 33–39 dBA."], "weerwoord": "'Minder verstorend dan verkeersgeluid' is iets anders dan 'niet verstorend'. Dezelfde onderzoeksgroep vond reacties vanaf 33 dBA.", "refs_extra": [167, 135]}, {"ids": [65], "naam": "Müller et al. (2025) – hinder verklaard door eerlijkheid", "wat": "Driejarige interdisciplinaire veldstudie naar hinder door windturbinegeluid.", "bevinding": "Geluidsniveaus verklaarden de hinder niet; ervaren eerlijkheid van het proces speelde een grote rol.", "zwakten": ["Andere grote studies vinden wel een duidelijke dosis-responsrelatie met het geluidsniveau.", "Dat procesfactoren meespelen, maakt de hinder niet minder reëel."], "weerwoord": "Als ervaren oneerlijkheid de hinder vergroot, is dat juist een reden voor een zorgvuldiger besluitvormingsproces en meer inspraak, niet om de hinder weg te zetten.", "refs_extra": [300, 278, 435]}, {"ids": [25], "naam": "Knies & Jetzkowitz (2026) – Duits panel kwaliteit van leven", "wat": "Panelonderzoek in Duitsland (2002–2022) naar woonafstand tot windturbines en kwaliteit van leven.", "bevinding": "Gemiddeld geen nadelige verandering in kwaliteit van leven binnen 6 km.", "zwakten": ["Secundaire analyses wezen op mogelijk lagere mentale kwaliteit van leven bij hogere turbinedichtheid.", "Een gemiddelde verbergt de groep die wel getroffen wordt."], "weerwoord": "Ook deze studie vindt aanwijzingen voor nadelige effecten op de mentale gezondheid bij hogere turbinedichtheid."}, {"ids": [378, 371], "naam": "McCunney et al. (2014) en Rubin et al. (2014) – kritische reviews", "wat": "Narratieve reviews die concluderen dat er geen bewijs is voor directe gezondheidseffecten van infrageluid, en die psychologische verklaringen bespreken.", "bevinding": "Verband met hinder erkend; geen bewijs voor directe effecten van infrageluid.", "zwakten": ["Gepubliceerd vóór belangrijke nieuwe studies (o.a. Bräuner 2019, Smith 2020, Forlim 2024, Mattsson 2026).", "'Geen bewijs gevonden' in een beperkte literatuur is geen bewijs van veiligheid."], "weerwoord": "Deze reviews zijn verouderd en erkennen zelf het verband met hinder. Nieuwere studies tonen effecten die toen nog niet bekend waren.", "refs_extra": [220, 186, 87]}, {"ids": [289], "naam": "Jalali et al. (2016) – slaap voor en na plaatsing", "wat": "Voor- en nametingsstudie met polysomnografie bij omwonenden van nieuwe windturbines.", "bevinding": "Objectieve slaapparameters veranderden niet significant.", "zwakten": ["Kleine groep en korte meetperiode.", "Dezelfde studie vond wel een verslechterde ervaren slaapkwaliteit."], "weerwoord": "De deelnemers ervoeren na plaatsing wel slechtere slaap. Voor de gezondheid van omwonenden is ervaren slaapkwaliteit een relevante uitkomst."}, {"naam": "Jakobsen (2005) – infrageluid ver onder de waarnemingsdrempel", "ids": ["G4"], "wat": "Een overzicht van alle destijds gepubliceerde metingen van infrageluid bij windturbines.", "bevinding": "Moderne turbines met de rotor vóór de mast produceren zeer zwak infrageluid, ver onder de waarnemingsdrempel, ook op korte afstand.", "zwakten": ["Gebaseerd op metingen bij turbines van vóór 2005, veel kleiner dan de huidige generatie.", "Gaat alleen over infrageluid onder 20 Hz, niet over laagfrequent geluid van 20–200 Hz.", "Gaat uit van de gemiddelde waarnemingsdrempel; individuele drempels verschillen tot 20 dB.", "Latere metingen vonden infrageluid tot 90 km en 10 km van windparken."], "weerwoord": "Deze studie is gebaseerd op turbines van vóór 2005 en gaat alleen over infrageluid. Grote moderne turbines produceren relatief meer laagfrequent geluid (Møller & Pedersen, 2011), dat bij woningen wel hoorbaar kan zijn (Doolan, 2013; Keith et al., 2019). De gemiddelde waarnemingsdrempel beschermt bovendien niet de mensen met een gevoeliger gehoor (Rajala et al., 2022).", "refs_extra": ["G50", "G47", "G188", "G454"]}, {"naam": "Nord2000 en ISO 9613-2 – ‘de berekening is gevalideerd’", "ids": ["G218", "G214"], "wat": "Vergelijkingen van rekenmodellen met metingen bij windturbines en luidsprekers.", "bevinding": "Voor A-gewogen niveaus benedenwinds over vlak terrein, tot ongeveer 1,5 km, kwamen berekening en meting goed overeen.", "zwakten": ["Gaat over A-gewogen niveaus, niet over lage tonen.", "Gunstige (benedenwindse) omstandigheden over vlak terrein; minder goed bovenwinds en in complex terrein.", "Voor infrageluid en laagfrequent geluid zijn modellen doorgaans niet gevalideerd.", "Voorbij 1 km kan ISO 9613-2 lage tonen onderschatten."], "weerwoord": "De validaties gelden voor A-gewogen geluid onder gunstige omstandigheden. Voor lage frequenties zijn gangbare modellen doorgaans niet gevalideerd (Stępień et al., 2024) en voorbij 1 km kan ISO 9613-2 onderschatten (Keith et al., 2018). Bij een operationeel windpark weken ISO 9613-2-voorspellingen tot 56,5 dB(Z) af van metingen (Echeverri Londoño & González, 2018).", "refs_extra": ["G34", "G14", "G95"]}];
